content.content:
export sidebar RightSidebarScope:
    side: right

    panels:
        - @{ReferencedFilesPanel}
        - @{UnderstandingPanel}

    concept: {RightSidebarConcept}

        up to half the sidebar's height, scrolling beyond that, and the
        understanding filling the rest, until they are resized.

    resizingPanels:
        The panels themselves can be resized, as the sidebar can. The edge
        between one panel and the next, where the lower panel's header meets
        the body of the one above, is a handle: dragging it up or down moves
export panel UnderstandingPanel:
    title: Understanding
    counted: false
    height: fill
    scrolls: true
    scrollbar: overflowing

    concept: {UnderstandingConcept}

concept UnderstandingConcept:
    pitch:
        The bottom panel of the @{RightSidebarScope}: the constraints
        the harness has taken from the spec for the running task.

    shape: {UnderstandingShape}

shape UnderstandingShape:
    description:
        It shows the running task's understanding file, as the
        @{ModeSystemPromptsScope} says, as it is written: one row per item of
        its Markdown list, in the file's order, its text wrapping rather than
        cut off. Each row is a box on the ribbon's tab row colour, #333333 in
        dark mode, with corners rounded 4 pixels, its text in small text with
        a 20 pixel line height, 8 pixels of padding either side and 6 above
        and below, so it is 32 pixels tall for a single line;
use /lib
from /ui import UiComponent

// A panel in a sidebar. What it is like follows from its properties, each
// switching the text of the panel section as the panel is extended.
export abstract anchor Panel extends UiComponent as panel:
    // Its header's title, or none for a panel with no header.
    title:: null:: string: null
    // Whether its header counts what it lists.
    counted:: boolean: false
    // How it takes its height: fill, fit, or share.
    height:: string: fill
    // Whether its contents scroll within it.
    scrolls:: boolean: true
    // Whether its scrollbar is always shown, or only while its contents
    // overflow: always or overflowing.
    scrollbar:: string: always

    panel:
        ${self.title != null ? "It has a header along its top, reading its title in small, semibold text, with a little padding around it. The header is on the theme's raised surface and the panel's body on its base surface, so the header stands slightly apart from the body, contrasting with it only a little, with no line between them." : "It has no header: its contents start at its top edge, on the theme's base surface."}

        ${self.counted ? "At its header's right, how many rows it lists, in smaller text, muted." : "It shows no count of what it lists."}

        ${self.height == "share" ? "It shares the height its sidebar's other panels leave with the other panels that share it, one above the other, split by a line that can be dragged to change their shares, each at least 80 pixels tall. They start with equal shares." : self.height == "fit" ? "It is only as tall as its contents need, taking no more of its sidebar's height." : "It fills the height its sidebar's other panels leave."}

        ${self.scrolls ? self.scrollbar == "overflowing" ? "Its contents scroll on their own when they are taller than it, with a scrollbar along its right only while they are, as the ScrollbarScope says; while they fit, it has no scrollbar and doesn't scroll at all." : "Its contents scroll on their own when they are taller than it, with a permanent scrollbar along its right, as the ScrollbarScope says." : "Its contents never scroll: it is as tall as they are."}

